INSERT INTO details (state, customer, label, value, kind, section, author) VALUES ('mi', 'Mindright Cannabis Co - New Baltimore', 'Salesforce note', 'MindRight is a Veteran owned and operated Cannabis Company focused on what''s important. Our friendly and "highly-dedicated" staff are working diligently at MindRight to bring you the best customer-experience possible. Our staff''s decades of knowledge allows us to educate customers on the innovations, possibilities, and incredible solutions that cannabis can provide you! Our open-floor showroom provides an inviting and immersive experience and allows users to feel welcomed and free at the same time. MindRight is setting a higher standard for what you''d expect from a Cannabis Retailer by addressing the needs of our customers by providing services and products that they can trust and rely on.', 'field', 'Relationship', 'salesforce import') ON CONFLICT(state, customer, label) DO UPDATE SET value = excluded.value, section = excluded.section;
