INSERT INTO details (state, customer, label, value, kind, section, author) VALUES ('mi', 'Muha Meds - Ypsilanti', 'Salesforce note', 'Muha Meds Retail Store, established in 2019 in Los Angeles, stands as a beacon of excellence in the cannabis industry. Our commitment to providing top-tier products shows in our expansive range of offerings, from edibles to vape supplies. At Muha Meds, we believe in more than just selling products; we are ambassadors for change, striving to destigmatize cannabis through our offerings. With a focus on ethics and sustainability, we curate a collection of cannabis goods that meet and exceed expectations. Experience premium cannabis products that transcend expectations. Join us on our journey to redefine the cannabis experience. Visit us today and discover the magic of premium cannabis products that transcend expectations.', 'field', 'Relationship', 'salesforce import') ON CONFLICT(state, customer, label) DO UPDATE SET value = excluded.value, section = excluded.section;
