INSERT INTO details (state, customer, label, value, kind, section, author) VALUES ('mi', 'Pure - New Baltimore Processing', 'Salesforce note', '<p>Our vision is to bring cannabis to the 21st century through high-quality craft cannabis operations. We work with local companies who use the best practices to produce a variety of High Quality concentrates, extracts and edibles, as well as offering our support to a number of brands while doing so. Call for Info and Bulk Pricing Options! 989-912-9105</p>', 'field', 'Relationship', 'salesforce import') ON CONFLICT(state, customer, label) DO UPDATE SET value = excluded.value, section = excluded.section;
