INSERT INTO details (state, customer, label, value, kind, section, author) VALUES ('mi', 'Pure - New Baltimore Processing MED', 'Salesforce note', '<p>**Shattered Thoughts: Your Destination for Creative Cannabis Products**</p><p>Shattered Thoughts is your go-to source for elevating the cannabis experience and delighting your customers with innovative products. We''re not just a brand; we''re a partner in your success, and we bring an unwavering commitment to quality and creativity in every product we craft.</p><p>Shattered Thoughts isn''t just about products; it''s about forging partnerships that drive success. Join our retailer network, and gain access to our premium cannabis creations, expert guidance, and a community of like-minded retailers who share our passion for excellence. Together, we''ll elevate the cannabis industry one inspired product at a time.</p><p>Visit our website to explore more: <a href="http://www.shatteredthoughts.com" rel="noopener noreferrer" target="_blank">www.shatteredthoughts.com</a></p>', 'field', 'Relationship', 'salesforce import') ON CONFLICT(state, customer, label) DO UPDATE SET value = excluded.value, section = excluded.section;
